export const DATA_16: ReadingTest[] = [
  { id: "rd-020", num: 20, title: "Đề 020", timeMin: 60, parts: [
    { title: "A Day at the Family Pig Farm", paragraphs: ["On a small family farm, the day begins early, long before sunrise, because pigs need food, water, and attention at regular times. The Nguyen family has raised pigs for three generations, and every member of the family, from grandparents to grandchildren, has a role to play. Farm life is not glamorous . It is often muddy, noisy, and tiring. Still, many families like the Nguyens say the work brings them closer together.", "By five in the morning, the youngest son is already outside, carrying buckets of feed toward the pens. Adult pigs eat a mix of corn, rice bran, and vegetable scraps, while young piglets receive a softer, more nutritious mixture to help them grow quickly and stay healthy. Feeding time is loud, because dozens of hungry pigs squeal and push toward the trough as soon as they smell breakfast. Once the animals are fed, the family checks the water supply, since pigs can quickly become sick if their water runs low or turns dirty.", "Newborn piglets need special care during their first few weeks of life. They are kept in a separate, warmer section of the barn, away from larger pigs that might accidentally hurt them. A farmer watches closely for any signs of illness, such as low energy, poor appetite, or unusual sounds. If a piglet seems sick, the family calls a local veterinarian right away, because problems can spread quickly through a crowded pen. Healthy piglets, on the other hand, are playful and curious, often exploring every corner of their small enclosure.", "Midday brings its own set of chores, many of which focus on keeping the pigs cool and comfortable. Pigs cannot sweat the way humans do, so farmers spray the pens with water or provide shallow pools of mud for the animals to lie in. Cleaning the pens is another important task, since dirty, wet floors can lead to infections. The Nguyen family rotates these jobs throughout the week so that no single person becomes too exhausted . Even the grandparents, who move more slowly than they once did, help by preparing feed mixtures in the kitchen.", "As evening approaches, the family gathers once more to feed the pigs a final time and lock the barn doors for the night. The work is far from finished, however, because sick animals sometimes need checking again before bed, and new piglets may need feeding every few hours. Despite the long hours, the family rarely complains. For them , raising pigs is not simply a business. It is a shared responsibility that has been passed down, and will likely continue to be passed down, for many years to come."], questions: [{ q: "According to the passage, why are newborn piglets kept separate from larger pigs?", options: ["Piglets need more space to run and play.", "The barn lacks enough room for every pig.", "Larger pigs might accidentally injure the smaller piglets.", "They are kept in a separate, warmer barn section."], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Pig farming mostly causes stress and conflict for families.", "Raising pigs is hard work that brings the family together.", "Newborn piglets need a warmer, separate barn section.", "All farm families must work together every single day."], answer: 1 }, { q: "According to the passage, why do farmers spray pens with water or give pigs mud pools?", options: ["Mud helps pigs digest their corn and rice bran.", "Water keeps piglets safe from larger, dangerous pigs.", "Pigs cannot sweat, so they need help staying cool.", "Spraying water helps prevent piglets from getting sick."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as part of the pigs' diet?", options: ["a mixture of corn and rice bran", "specially prepared fish oil supplement mixtures", "vegetable scraps mixed into their feed", "a softer mixture for young piglets"], answer: 1 }, { q: "The word \"glamorous\" in paragraph 1 is closest in meaning to _______.", options: ["grammatically correct", "mildly interesting", "elegant or exciting", "extremely dangerous"], answer: 2 }, { q: "The word \"exhausted\" in paragraph 4 is closest in meaning to _______.", options: ["extremely tired", "somewhat sleepy", "financially ruined", "thoroughly explained"], answer: 0 }, { q: "The word \"them\" in paragraph 5 refers to _______.", options: ["the piglets", "sick animals", "the family", "the barn doors"], answer: 2 }, { q: "What can be inferred about why the Nguyen family continues raising pigs despite the difficult, tiring work?", options: ["They value the shared purpose the work gives them.", "Tiredness from the work makes them work even harder.", "They believe farming will soon become much easier.", "Piglets are kept separate from larger, older pigs."], answer: 0 }, { q: "What is the author's overall attitude toward the Nguyen family's farm life, as expressed in the passage?", options: ["Neutral - simply listing chores without any real feeling.", "Admiring - respecting their dedication despite the difficult work.", "Worried - concerned mainly about piglet illness and disease.", "Amused - finding the noisy feeding time entertaining."], answer: 1 }, { q: "According to the passage, what do grandparents in the family do to help with farm work?", options: ["They call the veterinarian whenever a pig seems sick.", "They check piglets for illness every single morning.", "They carry heavy buckets of feed to the pens.", "They help by preparing feed mixtures in the kitchen."], answer: 3 }] },
    { title: "The Miracle of Seeds: Nature's Time Capsules", paragraphs: ["That a seed can remain dormant for years, decades, or even centuries before germinating is one of the more remarkable feats of biological engineering, yet the mechanisms enabling this suspended animation were only partially understood until relatively recently. A seed is not simply a dormant plant waiting passively for the right conditions; it is, more accurately, a highly engineered survival capsule, containing an embryo, a food reserve, and a protective coat all calibrated to delay development until circumstances favor survival.", "Dormancy itself is not a single phenomenon but rather several distinct strategies, each shaped by the evolutionary pressures a species has faced. Physical dormancy, in which a hard seed coat physically prevents water from reaching the embryo, tends to characterize species from fire-prone or unpredictable environments, where premature germination could prove fatal. Physiological dormancy, by contrast, involves internal chemical inhibitors that must be broken down gradually, often through prolonged cold exposure, a process that ensures seeds do not sprout during a brief midwinter thaw only to be killed by returning frost.", "Reports of seeds germinating after extraordinary periods of dormancy have periodically captured public attention, and while some widely circulated claims have not withstood scientific scrutiny , at least one case - a date palm seed recovered from an archaeological site and radiocarbon-dated to roughly two thousand years old - has been rigorously verified and successfully germinated, suggesting that some seeds possess repair mechanisms capable of correcting molecular damage accumulated across millennia.", "This longevity has practical significance well beyond scientific curiosity. Seed banks, of which the Svalbard Global Seed Vault is perhaps the most famous, rely on the assumption that properly dried and frozen seeds can preserve genetic diversity for centuries, offering a safeguard against crop failures, disease outbreaks, or the kind of catastrophic event that could otherwise eliminate irreplaceable plant varieties entirely. Whether current storage techniques will prove adequate across such extended timescales, however, remains an open question that only time itself can ultimately answer.", "Breaking dormancy, once conditions are favorable, requires seeds to detect a combination of environmental cues - adequate moisture, appropriate temperature, and, for some species, exposure to light or even the chemical signature of smoke following a wildfire. This sensitivity to smoke, intriguingly, connects directly to the fire-adapted dormancy strategies described earlier, since species that evolved hard seed coats to survive fire have often simultaneously evolved germination triggers that specifically exploit the post-fire environment, when competition from other plants is temporarily reduced and nutrients from ash are freshly available.", "Whether humanity will ever fully decode the biochemical mechanisms underlying extreme seed longevity remains uncertain, though ongoing research into the proteins and repair enzymes involved continues to narrow the gap between anecdote and rigorous explanation. What does seem clear is that seeds represent far more than a convenient means of plant reproduction; they are, in a very literal sense, biological time capsules, each one carrying not only genetic information but also an evolved strategy for surviving whatever unpredictable future its species might eventually face."], questions: [{ q: "What is the main idea of the passage?", options: ["Seed dormancy mechanisms are now fully understood by scientists.", "Seeds use varied, evolved strategies to survive long dormancy periods.", "One ancient date palm seed germinated after two millennia.", "All seeds remain dormant for centuries before finally germinating."], answer: 1 }, { q: "According to the passage, why have some fire-adapted species evolved germination triggers linked to smoke?", options: ["Smoke chemically destroys the seed coat, allowing water inside.", "A hard seed coat prevents water reaching the embryo.", "Post-fire conditions offer reduced competition and fresh nutrients.", "Fire increases soil temperature enough to break dormancy."], answer: 2 }, { q: "According to the passage, what allowed researchers to confirm the age of the verified ancient date palm seed?", options: ["Historical records documented exactly when the seed was buried.", "Genetic testing revealed the seed's species and approximate age.", "Some widely circulated claims have not withstood scrutiny.", "Radiocarbon dating confirmed the seed's age at the site."], answer: 3 }, { q: "According to the passage, all of the following are mentioned as environmental cues that can trigger germination EXCEPT :", options: ["a sudden drop in atmospheric air pressure", "light exposure required by all seed species", "adequate moisture and appropriate temperature levels", "the chemical signature of smoke after fire"], answer: 0 }, { q: "The word \"inhibitors\" in paragraph 2 is closest in meaning to _______.", options: ["cold temperatures", "blocking substances", "inhabited areas", "weak stimulants"], answer: 1 }, { q: "The word \"scrutiny\" in paragraph 3 is closest in meaning to _______.", options: ["public attention", "strict punishment", "careful examination", "casual glance"], answer: 2 }, { q: "The phrase \"This longevity\" in paragraph 4 refers to _______.", options: ["crop failure risk", "genetic diversity", "the Seed Vault", "extended seed viability"], answer: 3 }, { q: "Based on the passage, what can be inferred about seeds capable of germinating after thousands of years?", options: ["They likely possess mechanisms that repair long-accumulated molecular damage.", "They will remain viable indefinitely under any storage condition.", "Molecular damage is what allows such seeds to germinate.", "A hard seed coat physically prevents water reaching the embryo."], answer: 0 }, { q: "What is the author's overall attitude toward claims of extreme seed longevity, as expressed in the passage?", options: ["Dismissive - arguing seed longevity claims are mostly false.", "Curious and cautious - impressed, yet noting real uncertainty.", "Alarmed - warning that seed banks will inevitably fail.", "Certain - confident science has fully solved seed longevity."], answer: 1 }, { q: "According to the passage, what is the main purpose of seed banks such as the Svalbard Global Seed Vault?", options: ["To sell rare seeds to farmers around the world.", "To breed entirely new, genetically modified plant species.", "Physical dormancy involves a hard seed coat blocking water.", "To preserve genetic diversity against future crop disasters."], answer: 3 }] },
    { title: "Educational Challenges for Children in Remote Mountainous Regions", paragraphs: ["That children in remote mountainous regions face educational obstacles largely absent from urban and lowland settings is well established, yet policymakers continue to underestimate just how deeply these obstacles are intertwined, such that addressing any single barrier in isolation rarely produces lasting improvement. Terrain, poverty, cultural expectations, and institutional neglect compound one another in ways that make mountain education reform considerably more complex than simple resource allocation would suggest.", "Among the most immediate obstacles is sheer physical distance: children in many mountain communities must walk for hours, often along unstable or seasonally impassable paths, simply to reach the nearest school. During the rainy season, when landslides and flooded streams render some routes entirely unusable, attendance in certain villages drops so sharply that entire cohorts effectively lose weeks of instruction, a loss that annual calendars rarely account for and that compounds year over year rather than resetting each term.", "Recruiting and retaining qualified teachers presents a related but distinct difficulty, since few newly trained educators, given a choice, elect to work in isolated postings offering minimal housing, limited connectivity, and few opportunities for professional advancement. The result, in many districts, is a rotating cast of underqualified or temporary instructors whose frequent turnover disrupts the continuity that early literacy and numeracy development particularly require - a dynamic that, tellingly, often does more to depress learning outcomes than the resource shortages typically blamed for the same statistics.", "Economic pressures compound these structural barriers, though their influence is neither uniform nor always straightforward. Many mountain families depend on children's labor for herding, farming, or household tasks, particularly during planting and harvest seasons, and the opportunity cost of forgone labor can outweigh a family's perceived long-term benefit of schooling, especially where local economic prospects for educated youth remain visibly limited. This calculation , rational within its own context, nonetheless perpetuates the very disadvantage that education might otherwise help resolve.", "That no single intervention has reliably closed these gaps is now widely acknowledged among researchers, even as boarding schools, mobile or itinerant teaching programs, and digital learning initiatives have each been piloted with partial success. Boarding schools improve attendance consistency but often at the cost of prolonged family separation that some communities resist; mobile teaching programs reduce travel burdens but struggle to scale given limited qualified staff; and digital initiatives, while promising in principle, frequently founder on inadequate electricity and connectivity infrastructure that mountainous terrain itself makes difficult to install.", "Whether emerging approaches - including community-based teacher training and satellite internet connectivity - will meaningfully narrow the gap between mountain and lowland educational outcomes remains uncertain, contingent on funding commitments and infrastructure investments that have historically been deprioritized relative to more visible, lower-cost interventions. What does appear increasingly clear, however, is that any durable solution must address the interlocking terrain, economic, and staffing barriers simultaneously rather than sequentially."], questions: [{ q: "What is the main idea of the passage?", options: ["Resource shortages, not teacher turnover, mainly explain poor outcomes.", "Mountain education barriers are interlinked and need combined solutions.", "Boarding schools improve attendance but separate children from families.", "No intervention has ever improved mountain education outcomes at all."], answer: 1 }, { q: "According to the passage, what does the author suggest is a more significant cause of poor learning outcomes in many mountain districts than resource shortages?", options: ["Children must walk for hours along unstable, impassable paths.", "Insufficient funding for school building construction and maintenance.", "Frequent turnover among underqualified, temporary teachers disrupts continuity.", "A shortage of textbooks and other basic classroom materials."], answer: 2 }, { q: "According to the passage, why might a mountain family's decision to prioritize children's labor over schooling be described as rational within its own context, even though it perpetuates disadvantage?", options: ["Families are legally required to use children for farming labor.", "Boarding schools improve attendance at the cost of separation.", "Schools charge fees that most mountain families cannot afford.", "Local prospects for educated youth appear too limited to outweigh lost labor."], answer: 3 }, { q: "According to the passage, all of the following are mentioned as limitations of proposed interventions EXCEPT :", options: ["boarding schools causing prolonged family separation", "satellite internet programs proving too expensive for any government", "digital initiatives limited by inadequate electricity and connectivity", "mobile teaching programs struggling to scale due to staff shortages"], answer: 1 }, { q: "The word \"compound\" in paragraph 1 is closest in meaning to _______.", options: ["chemically combine", "slightly affect", "intensify jointly", "financially reward"], answer: 2 }, { q: "The word \"founder\" in paragraph 5 is closest in meaning to _______.", options: ["improve gradually", "fail or collapse", "expand rapidly", "become founders"], answer: 1 }, { q: "The phrase \"This calculation\" in paragraph 4 refers to _______.", options: ["long-term benefit", "planting and harvest seasons", "the labor-versus-schooling trade-off", "visibly limited prospects"], answer: 2 }, { q: "Based on the passage, what can be inferred about why addressing terrain, economic, and staffing barriers sequentially, rather than simultaneously, has failed to produce durable improvement?", options: ["Sequential approaches fully resolve each barrier, yet gains still disappear entirely.", "Durable improvement is what allows barriers to become interlinked.", "Boarding schools improve attendance consistency at the cost of separation.", "The barriers reinforce each other, so isolated fixes leave others intact."], answer: 3 }, { q: "What is the author's overall attitude toward efforts to improve mountain education, as expressed in the passage?", options: ["Critical - mainly blaming families for undervaluing education.", "Analytical and cautiously hopeful - stressing complexity without dismissing progress.", "Despairing - insisting no meaningful progress is achievable at all.", "Celebratory - praising digital initiatives as the definitive solution."], answer: 1 }, { q: "According to the passage, what effect does the rainy season have on school attendance in some mountain villages?", options: ["Schools officially close for the entire rainy season nationwide.", "Recruiting and retaining qualified teachers presents a related difficulty.", "Impassable routes cause sharp, cumulative drops in attendance.", "Attendance drops only slightly and recovers immediately afterward."], answer: 2 }] },
    { title: "Implicit Bias and the Impact of Names on Opportunity", paragraphs: ["Not only have researchers long suspected that a person's name might subtly influence how others perceive their competence or trustworthiness, but a substantial body of experimental evidence has since confirmed that such effects, while often small in any single interaction, can accumulate into consequential disparities across a lifetime of hiring decisions, academic evaluations, and social interactions. Whether these effects stem primarily from racial or ethnic association, perceived socioeconomic status, or some combination of the two, remains a question that continues to divide researchers in the field. [1]", "The most widely cited evidence comes from correspondence audit studies, in which researchers submit otherwise identical résumés under different names - some conventionally associated with racial or ethnic minority groups, others with the majority population - to real job postings. Findings across numerous such studies, conducted in multiple countries and industries, consistently suggest that résumés bearing names associated with minority groups receive fewer callbacks than identical résumés bearing majority-associated names, though the magnitude of this gap varies considerably depending on industry, region, and the specific names tested. [2]", "That this callback gap arises from implicit rather than deliberate bias is the interpretation favored by most researchers in the field, though this attribution rests substantially on inference rather than direct observation of evaluators' mental states. Implicit association research, which measures the speed with which individuals pair names or faces with positive or negative concepts, does suggest that most people, regardless of their own stated attitudes, harbor measurable associations that could plausibly translate into the biased evaluations documented in audit studies - a connection that is suggestive rather than conclusively demonstrated. [3]", "Some individuals, aware of this dynamic, engage in what researchers term identity-related name adaptation - adopting anglicized nicknames, using initials rather than full first names, or otherwise modifying self-presentation on résumés and applications in an effort to circumvent anticipated bias. Whether this strategy meaningfully improves individual outcomes remains empirically contested: some studies report modest improvements in callback rates following such adaptation, while others find the effect negligible once other résumé characteristics are controlled for, suggesting that name adaptation may function more as a coping mechanism than a reliable solution.", "Critics of the individual-adaptation framing argue that placing the burden of adaptation on affected individuals risks obscuring the structural nature of the problem, effectively asking those disadvantaged by bias to expend additional, unevenly distributed effort simply to reach parity with unaffected peers. [4] Proponents of structural intervention instead advocate for blind or anonymized resume-screening procedures, in which identifying information, including names, is withheld from initial evaluators, a practice some organizations have adopted with reportedly promising, though not universally consistent, results.", "Blind screening, however, addresses only the earliest stage of evaluation and does not necessarily eliminate bias that may resurface during interviews, reference checks, or later promotion decisions, where anonymity becomes increasingly difficult to maintain. Some researchers therefore caution against treating anonymized screening as a comprehensive solution, arguing instead that it should be understood as one component within a broader set of interventions - including structured interview protocols and standardized evaluation criteria - that collectively, though not individually, may meaningfully reduce bias across the full employment pipeline.", "Taken together, the evidence does not support the strong claim that names alone determine life outcomes, nor does it support the dismissive claim that documented callback disparities are statistical noise without real consequence; rather, it supports the more modest, and considerably less rhetorically satisfying, conclusion that names function as one among many subtle signals that, in aggregate and over time, can meaningfully shape opportunity - a conclusion that resists easy translation into either alarmist headlines or complacent dismissal."], questions: [{ q: "What is the main idea of the passage?", options: ["Correspondence audit studies show minority names receive fewer callbacks.", "Names subtly shape opportunity as one signal among many, not a sole determinant.", "Documented callback disparities are essentially meaningless statistical noise.", "A person's name alone completely determines lifetime outcomes."], answer: 1 }, { q: "According to the passage, what interpretation do most researchers favor regarding the cause of callback disparities, and on what basis?", options: ["Researchers submit otherwise identical résumés under different names.", "Deliberate, conscious discrimination, confirmed through evaluator interviews.", "Implicit bias, inferred indirectly rather than directly observed.", "Socioeconomic status alone, confirmed through controlled income data."], answer: 2 }, { q: "According to the passage, why do some researchers caution against treating blind résumé screening as a complete solution?", options: ["Blind screening has been shown to increase bias during interviews.", "Some organizations have adopted anonymized screening with promising results.", "Most organizations have already abandoned anonymized screening entirely.", "Bias may resurface later, when anonymity becomes harder to maintain."], answer: 3 }, { q: "According to the passage, which of the following is NOT presented as a genuinely unresolved question?", options: ["whether résumés with minority-associated names receive fewer callbacks on average", "whether racial association or socioeconomic status better explains the effect", "whether name adaptation reliably improves individual callback outcomes", "whether implicit bias is the true mechanism behind callback gaps"], answer: 0 }, { q: "The word \"circumvent\" in paragraph 4 is closest in meaning to _______.", options: ["travel around", "get around", "slightly reduce", "openly confront"], answer: 1 }, { q: "The word \"parity\" in paragraph 5 is closest in meaning to _______.", options: ["partial payment", "slight advantage", "equal standing", "formal agreement"], answer: 2 }, { q: "The phrase \"this attribution\" in paragraph 3 refers to _______.", options: ["the implicit-bias interpretation", "direct observation", "mental states", "audit study findings"], answer: 0 }, { q: "Based on the passage, what can be inferred about the relationship between the uncertainty surrounding the causes of naming bias and the practical importance of addressing it?", options: ["Once causes are fully identified, disparities will certainly disappear entirely.", "Practical significance is what caused researchers to agree on causes.", "Correspondence audit studies use otherwise identical résumés.", "Causal uncertainty does not reduce the real-world significance of the disparities."], answer: 3 }, { q: "What is the author's overall stance toward the evidence on naming bias, as expressed in the passage?", options: ["Dismissive - arguing callback disparities reflect meaningless statistical noise.", "Measured - resisting both alarmist and dismissive interpretations of evidence.", "Alarmed - certain that hiring discrimination is rampant and deliberate.", "Advocative - firmly endorsing blind screening as the definitive fix."], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This uncertainty about underlying causes does not, however, diminish the practical significance of the documented disparities themselves.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }] },
  ] },
  { id: "rd-149", num: 149, title: "Đề 149", timeMin: 60, parts: [
    { title: "The Ghost Detective: A Life Spent Chasing Shadows", paragraphs: ["Elias Whitmore spent forty years investigating reports of haunted houses, yet he never once claimed to have found a real ghost. Instead, he built a long career out of proving that most spooky stories have a simple, ordinary explanation. Local newspapers nicknamed him \"the ghost detective\" because he approached every case the way a police officer approaches a crime scene, carefully gathering evidence instead of trusting rumor. By the time he retired, he had personally examined more than three hundred reported hauntings across the country.", "Whitmore did not originally set out to hunt ghosts. As a young engineer, he was asked by a worried family to check strange noises coming from their attic late at night. He expected to find nothing more than an odd draft, and that is exactly what he found: a loose roof tile knocking against a chimney whenever the wind picked up outside. The family felt relieved, and word of his calm, practical approach spread quickly through the neighborhood, reaching people he had never met.", "Over time, Whitmore developed a standard toolkit for every investigation he accepted. He carried a notebook, a thermometer, and a simple camera, and he always interviewed witnesses separately so that their stories could not influence one another. He also tested for common tricks, such as hidden speakers or drafty windows, before he ever considered a stranger possibility, and he would return to a house at different hours to see whether the strange sounds changed with the weather. Some clients felt disappointed when he explained away their ghost, but most said they felt better once they finally understood what was really happening inside their own home.", "His most famous case involved an old theater where actors refused to perform alone at night. Whitmore spent three weeks inside the building, sleeping in a different room each time, and he eventually traced the eerie footsteps to a family of raccoons living beneath the stage. The theater owner was so grateful that he offered Whitmore free tickets for life, though Whitmore later admitted it had also taught him something important: fear often grows larger in the dark than any actual danger ever could.", "Whitmore never grew rich from his work, and he rarely appeared on television, preferring quiet fieldwork to public attention of any kind. When he died at the age of seventy-eight, several newspapers wrote that he had \"debunked more ghosts than anyone in history,\" though Whitmore himself would probably have argued that he had simply solved a long list of ordinary, forgettable problems. Today, a small group of amateur investigators still follows his methods, carrying notebooks and thermometers into old houses, hoping to bring the same patient curiosity to cases he never lived to see."], questions: [{ q: "According to the passage, what first led to Whitmore being called \"the ghost detective\"?", options: ["A newspaper hired him to explain a local ghost story", "A theater owner asked him to explain frightening footsteps", "A family asked him to investigate strange sounds in their attic", "A young engineer discovered noises coming from his own workshop"], answer: 2 }, { q: "The word \"practical\" in paragraph 2 is closest in meaning to _______.", options: ["sensible", "overly cautious", "mysterious", "commonly practiced"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Whitmore used a notebook and thermometer to record strange sounds", "Whitmore became famous mainly for the ghosts he successfully proved were real", "Whitmore proved that haunted houses do not actually exist anywhere", "Whitmore built a career on finding ordinary causes for reported hauntings"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as something Whitmore did during his investigations?", options: ["personally inspecting the source of the strange noises himself", "consulting a professional psychic for a second opinion", "carrying a notebook, a thermometer, and a small camera", "sleeping in a different room of the building each night"], answer: 1 }, { q: "The word \"it\" in paragraph 4 refers to _______.", options: ["the theater case", "the theater owner", "the free tickets", "the raccoon family"], answer: 0 }, { q: "What did Whitmore discover was causing the footsteps in the theater?", options: ["a family of mice behind the walls", "the theater owner walking through the building alone", "loose roof tiles repeatedly knocking against the old chimney", "a family of raccoons living beneath the stage"], answer: 3 }, { q: "The word \"eerie\" in paragraph 4 is closest in meaning to _______.", options: ["very frightening", "strange and frightening", "abandoned", "early"], answer: 1 }, { q: "It can be inferred from the passage that Whitmore believed fear is often caused mainly by _______.", options: ["the unfamiliar sounds heard inside old buildings", "real danger increasing because people feel afraid", "uncertainty in the dark rather than real danger", "the raccoons that were living beneath the theater stage"], answer: 2 }, { q: "According to the passage, how did Whitmore prefer to interview witnesses?", options: ["by interviewing each witness separately from the others", "by interviewing all of the witnesses together in one room", "by writing detailed letters to witnesses after each case", "by recording interviews using a hidden camera"], answer: 0 }, { q: "What is most likely the author's main purpose in writing this passage?", options: ["to explain why the theater raccoons frightened the actors", "to mock people who believe old houses are haunted", "to argue that ghost hunting should become a formal profession", "to describe how Whitmore approached and explained reported hauntings"], answer: 3 }] },
    { title: "Hồ Tây: Between Legend and Geology", paragraphs: ["Few bodies of water in Hanoi carry as many competing origin stories as Hồ Tây, the city's largest lake, where a golden buffalo, a nine-tailed fox, and a wandering monk each appear in different retellings of how the basin first took shape. Although the tales disagree on the details, most agree on one point: something enormous once thrashed across the land, carving out a hollow that the Red River later filled. Geologists arrived at a strikingly similar image, though their explanation involves neither buffalo nor fox.", "That the lake began as a bend in a much larger river is not, in fact, a modern discovery invented to replace folklore; it was suspected by local chroniclers as early as the fifteenth century, long before anyone had the tools to confirm it. Their reasoning rested on simple observation rather than science: the lake's curved shoreline echoed the shape of a river bend, and old fishermen recalled that the water occasionally rose and fell in a way that matched flooding patterns further upstream. What they lacked was proof, not intuition, and proof would not arrive for another five hundred years.", "Modern surveys suggest that Hồ Tây is what geographers call an oxbow lake, a curved body of water left behind when a meandering river cuts across the neck of one of its own loops and abandons the old channel entirely. Sediment cores taken from the lake bed tend to support this reading: layers of river silt sit beneath layers of still-water mud, a sequence that would be difficult to explain if the lake had formed in any other way. The Red River, researchers note, drifted westward over centuries, leaving the loop that became Hồ Tây stranded on dry land.", "Seen this way, the golden buffalo and the drifting river are not really rivals for the truth; they may simply be two languages describing the same slow event. A community without instruments for measuring erosion still needed a way to explain why a river had abandoned its old bed, and a creature large enough to gouge a lake from solid ground offered an answer that made sense on a human scale, one that a shifting channel, invisible over a single lifetime, could not easily provide.", "Over the centuries, the lake has answered to several other names, each pointing toward a different chapter of the same layered story. Because a dragon was once said to have descended into its waters, some old maps labeled it the Lake of the Descending Dragon; because fog frequently settled over its surface at dawn, later writers preferred the Mist Lake instead. Only in more recent centuries did \"West Lake,\" a name describing nothing more than its position relative to the old citadel, become the label most commonly used today, arguably the least imaginative of them all.", "Whether a visitor prefers the buffalo, the fox, or the meandering river likely depends less on evidence than on what kind of story they came looking for in the first place. The geological account may be the one confirmed by sediment cores and satellite imagery, yet it has not managed to replace the older tales, which continue to appear in temple inscriptions and tourist guidebooks alike, suggesting that a lake's true origin can be settled long before its imagined ones are."], questions: [{ q: "According to the passage, what physical feature convinced early chroniclers, before modern science, that the lake had once been part of a larger river?", options: ["written records left behind by earlier geologists", "the curved outline of the lake's own shoreline", "the unusual color of the water during flooding", "measurements taken from boats crossing the lake"], answer: 1 }, { q: "The word \"thrashed\" in paragraph 1 is closest in meaning to _______.", options: ["moved slightly", "flooded", "threaded", "moved violently"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as evidence used to support the idea that Hồ Tây was once part of the Red River?", options: ["carbon dating of fish bones pulled from the lake bed", "the shape of the lake's shoreline observed by chroniclers", "layers of silt and mud found in sediment cores", "images captured by satellites of the lake area"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["sediment cores confirm that Hồ Tây was once a river bend", "geological evidence has fully replaced the region's older legends", "local legends and modern geology describe the same origin differently", "every lake in Vietnam has both a legend and a scientific origin"], answer: 2 }, { q: "What do the sediment layers found beneath Hồ Tây reveal, according to the passage?", options: ["volcanic ash mixed with layers of ancient river sand", "river silt lying beneath layers of still-water mud", "fish fossils buried beneath centuries of old city waste", "still-water mud lying above thick layers of ancient rock"], answer: 1 }, { q: "The word \"its\" in paragraph 5 refers to _______.", options: ["the fog", "the Descending Dragon", "the old maps", "the lake"], answer: 3 }, { q: "It can be inferred from the passage that local chroniclers in the fifteenth century and modern geologists reached similar conclusions about the lake mainly because _______.", options: ["both groups noticed the same river-like shape of the basin", "both groups had access to detailed maps of the river", "modern satellite images convinced early chroniclers of the river's shift", "sediment cores were first collected in the fifteenth century"], answer: 0 }, { q: "The word \"gouge\" in paragraph 4 is closest in meaning to _______.", options: ["lightly scratch", "flood", "dig out", "gauge"], answer: 2 }, { q: "According to the passage, what does the name \"West Lake\" describe?", options: ["the lake's shape as seen from above", "the lake's position relative to the old citadel", "a dragon said to have descended into the water", "the fog that settles over the lake at dawn"], answer: 1 }, { q: "What is most likely the author's main purpose in writing this passage?", options: ["to prove that sediment cores never lie about the past", "to insist that the geological explanation is the only correct one", "to criticize local chroniclers for lacking scientific proof", "to explore how legend and geology explain the same lake"], answer: 3 }] },
    { title: "Diagnosing the Mind: Certainty and Its Limits in Modern Psychiatry", paragraphs: ["Unlike a fractured bone, confirmable on an X-ray regardless of who reads the image, a diagnosis of major depressive disorder rests on a clinician's judgment about symptoms that patients themselves must first describe in words. This gap between the visible certainty of physical medicine and the interpretive nature of psychiatric assessment has shaped the field for more than a century, even though most patients assume that a diagnosis reflects something as fixed as a broken bone.", "The manuals psychiatrists use to standardize diagnosis have evolved considerably, not always in a straight line toward greater precision. Early twentieth-century systems relied heavily on individual clinicians' impressions, producing diagnoses that varied so widely between hospitals that a patient labeled schizophrenic in one city might have received an entirely different diagnosis elsewhere. Later revisions introduced detailed symptom checklists specifically to curb this inconsistency, and reliability, meaning the degree to which clinicians agree, did improve measurably once checklists replaced impression alone.", "That reliability improved, however, says little about whether the categories correspond to anything biologically real. [1] Two clinicians using an identical checklist can now agree with reasonable consistency that a patient meets the criteria for a disorder, yet this kind of agreement demonstrates only that the checklist is applied consistently, not that the category carves nature at a genuine joint. [2] Critics have long argued that many diagnostic boundaries were drawn by committee consensus rather than by any biological marker, [3] and that a checklist can be reliable while still describing a category later found, in researchers' own phrasing, \"insufficiently specific.\" [4]", "Defenders of the current system concede this point only partially. They argue that even an imperfect category can guide effective treatment, much as early classifications of fever guided useful remedies long before germ theory explained why those remedies worked. On this view, a diagnosis functions less as a final scientific verdict and more as a working hypothesis, flexible enough to be revised as research advances, but stable enough meanwhile to connect patients with therapies that measurably reduce their suffering.", "The tension between these two positions resurfaces whenever a new edition of a diagnostic manual is prepared, since committees must decide whether to split a broad category, merge several into one, or leave a contested boundary untouched, and each choice carries consequences for research funding, insurance coverage, and how patients understand their own experience. A decision that looks purely technical on paper tends to ripple outward into areas the manual's authors never directly intended to influence.", "For patients, this uncertainty rarely announces itself; a diagnosis is generally delivered with more confidence than the research would strictly justify, if only because clinical practice cannot pause for a debate researchers themselves have not resolved. A label can open doors, granting access to medication, therapy, or workplace accommodations otherwise difficult to obtain, and yet the same label can just as easily close others, attaching a stigma that lingers long after symptoms have eased.", "None of this suggests psychiatric diagnosis is arbitrary or without value; it suggests instead that the field's categories should be understood as provisional tools rather than settled facts, useful precisely because they are periodically revised rather than despite it. A century of revision has not produced certainty, and there is little reason, given the field's own history, to expect that the next revision will finally deliver it."], questions: [{ q: "According to the passage, why did diagnoses for the same patient sometimes differ between hospitals in the early twentieth century?", options: ["checklists were applied inconsistently across different hospitals", "hospitals disagreed about which manual edition to adopt", "clinicians relied on personal impressions rather than a shared checklist", "patients described their symptoms in inconsistent ways"], answer: 2 }, { q: "The word \"carves\" in paragraph 3 is closest in meaning to _______.", options: ["accurately divides", "roughly divides", "measures", "curves"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a factor discussed in relation to psychiatric diagnostic categories?", options: ["checklists that substantially improved reliability and agreement among different clinicians", "boundaries drawn largely through professional committee consensus", "labels that can restrict access to workplace accommodations", "clinical trials comparing new medications across countries"], answer: 3 }, { q: "Based on the passage, what can be inferred about the relationship between diagnostic reliability and diagnostic validity in psychiatry?", options: ["checklists were introduced specifically to strengthen a category's biological basis", "improving reliability does not necessarily establish that a category is biologically valid", "biological validity was established first, which then improved clinician agreement", "early classification systems relied heavily on individual clinicians' impressions"], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This does not mean the checklist itself is flawed, only that reliability and validity are different achievements entirely.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Checklists have made psychiatric diagnoses more consistent between clinicians", "Psychiatric categories are now fully confirmed as biologically real conditions", "All fields of medicine share the same diagnostic uncertainty as psychiatry", "Psychiatric diagnosis has grown more reliable without becoming scientifically certain"], answer: 3 }, { q: "The word \"this\" in paragraph 6 refers to _______.", options: ["the manual's authors", "the reliability-validity gap", "insurance coverage", "committee decisions"], answer: 1 }, { q: "According to the passage, what do defenders of the current diagnostic system compare psychiatric categories to, in order to justify their usefulness?", options: ["checklists that made clinician agreement more reliable", "physical injuries that can be confirmed by X-ray", "early classifications of fever that guided effective remedies", "biological markers identified through laboratory testing"], answer: 2 }, { q: "The word \"ripple\" in paragraph 5 is closest in meaning to _______.", options: ["spread gradually", "spread violently", "shrink", "ripen"], answer: 0 }, { q: "What is most likely the author's main purpose in writing this passage?", options: ["to describe how psychiatric diagnostic checklists were first developed", "to dismiss the entire field of psychiatric diagnosis as unscientific", "to defend the current diagnostic manual against all criticism", "to explain why psychiatric diagnosis remains scientifically provisional"], answer: 3 }] },
    { title: "Personifying Evil: The Shifting Meaning of Satan in Religious and Philosophical Thought", paragraphs: ["Nowhere in the earliest layers of the Hebrew Bible does the word \"satan\" function as a proper name; rather, it denotes a role, an adversary or obstacle, applied at various points to human opponents and even, in one episode, to an angel blocking a prophet's path. Only gradually did the term migrate from common noun to something closer to a title, and only later still did it harden into the name of a singular cosmic figure.", "That migration accelerated during the Second Temple period, when a wave of apocalyptic and intertestamental literature began imagining a more individuated antagonist, one who commanded lesser spirits and opposed a divine order on a scale earlier texts had never suggested. Scholars have proposed, though rarely with full consensus, that contact with dualistic currents circulating in the wider region may have supplied some of the imaginative vocabulary for this expansion, even as the underlying theological framework remained resolutely monotheistic throughout.", "Not until several centuries after these apocalyptic elaborations, and largely through texts that never entered the biblical canon, did a fully narrated rebellion story take shape: a proud angel, cast out of a celestial court for refusing to submit, falling alongside a host of followers into a newly imagined underworld. Later Christian theology absorbed fragments of this narrative unevenly, so that by the medieval period preachers could reference a coherent fall-of-Lucifer story that the biblical text itself, read on its own terms, never actually tells in one continuous place.", "It was Milton, writing centuries afterward, who gave this scattered tradition its most psychologically vivid form, and not always to the effect he may have intended; so persuasive is the defiant, self-justifying voice he gave the character in Paradise Lost that generations of readers have debated whether the poem accidentally makes its villain into something closer to a tragic protagonist. Whether this effect was a deliberate irony or an unintended consequence of dramatic craftsmanship remains, even now, a genuinely open question among literary scholars, one Milton's own prose writings do little to resolve.", "Meanwhile, a rather different reinterpretation was unfolding outside literary and theological circles. Enlightenment skeptics, and later a range of psychological thinkers, increasingly treated the figure less as a literal being than as a symbol, variously read as the projection of human rebellion, of unacknowledged desire, or of what one influential twentieth-century theorist termed the repressed \"shadow\" side of the self. None of these readings claims to displace the theological one so much as to run alongside it, addressing a different kind of question about why the symbol has proven so durable .", "Set against other religious traditions, this trajectory looks less inevitable than it might first appear. Traditions built on a genuinely dualistic cosmology, in which good and evil are conceived as co-eternal rather than one being a corruption of the other, never needed to explain how a figure of pure evil could emerge from a wholly good creation; monotheistic traditions, by contrast, inherited exactly that difficulty, and the elaborate personification traced across the earlier paragraphs can be read as one extended, still-unfinished attempt to resolve it. Historians of religion still dispute how completely this project has succeeded.", "None of this implies that the figure's meaning has settled into a final form, nor is there strong reason to expect that it will. Each era, it seems, has projected onto Satan whatever question about evil, agency, or rebellion happened to preoccupy it most, so that tracing the figure's history amounts less to charting one continuous portrait than to reading a series of successive, era-specific answers to a single unresolved theological problem."], questions: [{ q: "What is the main idea of the passage?", options: ["Milton's Paradise Lost transformed Satan into a sympathetic character", "The figure of Satan has been continually reshaped by each era's concerns", "Modern psychology has fully replaced the religious understanding of Satan", "Every religious tradition eventually personifies evil in the same way"], answer: 1 }, { q: "According to the passage, what was the original meaning of the term \"satan\" in the earliest parts of the Hebrew Bible?", options: ["a title for a cosmic being commanding lesser spirits", "a name for a specific fallen angel", "a symbol representing unacknowledged human desire", "a role describing an adversary or obstacle"], answer: 3 }, { q: "The word \"migrate\" in paragraph 1 is closest in meaning to _______.", options: ["gradually shifted", "suddenly shifted", "translated", "emigrated"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a way scholars or thinkers have understood the figure of Satan?", options: ["an individuated antagonist commanding lesser spirits", "a tragic and sympathetic literary protagonist in Milton's poem", "a literal deity worshipped in ancient Near Eastern temples", "a psychological symbol of repressed human desire"], answer: 2 }, { q: "According to the passage, what did later Christian preachers do with the rebellion narrative surrounding Satan?", options: ["they rejected it entirely as a much later, unbiblical narrative invention", "they referenced it as a coherent, continuous fall-of-Lucifer story", "they debated whether it made the figure sympathetic", "they traced it directly to a single continuous biblical passage"], answer: 1 }, { q: "The word \"this\" in paragraph 6 refers to _______.", options: ["that difficulty", "monotheistic traditions", "dualistic cosmology", "the personification of Satan"], answer: 3 }, { q: "Based on the passage, what can be inferred about the possible influence of dualistic currents on the Second Temple period's more individuated portrayal of Satan?", options: ["it may have contributed partly, though scholars do not agree", "it definitely caused the shift toward monotheistic personification", "it fully explains every aspect of the new portrayal", "the individuated portrayal of Satan influenced dualistic currents elsewhere"], answer: 0 }, { q: "The word \"durable\" in paragraph 5 is closest in meaning to _______.", options: ["briefly popular", "religious", "long-lasting", "curable"], answer: 2 }, { q: "According to the passage, what distinguishes traditions with a dualistic cosmology from monotheistic traditions regarding the origin of evil?", options: ["monotheistic traditions, however, need not explain evil's origin at all", "dualistic traditions need not explain evil's emergence", "dualistic traditions debate whether Satan is a tragic hero", "monotheistic traditions view good and evil as co-eternal"], answer: 1 }, { q: "What is most likely the author's main purpose in writing this passage?", options: ["to argue that Milton intentionally made Satan a hero", "to prove that Satan never existed as a real being", "to argue that monotheistic religions are logically inconsistent", "to trace how interpretations of Satan have changed across eras"], answer: 3 }] },
  ] },
  { id: "rd-155", num: 155, title: "Đề 155", timeMin: 60, parts: [
    { title: "The Cyclo's Second Life", paragraphs: ["The cyclo, a three-wheeled pedicab with a padded seat mounted in front of the driver, first appeared on the streets of Saigon in the late 1930s. A French mechanic is said to have adapted the design from rickshaws, swapping a single runner for pedals so one driver could carry two seated passengers. Within twenty years the vehicle had spread north to Hanoi, where narrow lanes suited it well. Its small turning radius suited the Old Quarter far better than any car could manage, and shopkeepers there quickly grew used to the sound of its bell.", "For much of the twentieth century the cyclo was simply how ordinary people got around a busy city. Office workers hailed one for the ride home, market vendors loaded baskets of vegetables onto its wide front seat, and parents sent children to school in one long before motorbikes became common. A single trip across town cost only a modest fare, rarely more than the price of a bowl of noodles. Drivers could usually be found waiting near almost any street corner, market gate, or railway station entrance.", "That everyday role began to shrink once the economic reforms of the 1980s opened the door to cheap imported motorbikes. Within a decade a motorbike could carry a whole family faster and farther than a pedaling driver ever could, and traffic in the largest cities grew thick with engines. Worried about congestion on the busiest roads, city authorities gradually restricted cyclos during peak hours. In several districts officials went further and banned the vehicles outright from entering at all, regardless of the hour or the purpose of the trip.", "Yet the cyclo did not disappear; instead it found a new audience among foreign visitors curious about the old city. Tour operators began packaging slow rides through the Old Quarter as a way to see temples and colonial buildings that a taxi would simply speed past without a second glance. Drivers who once carried shoppers now doubled as informal guides along routes pedaled for decades. Hotels near the historic core now keep a small fleet parked out front for exactly this purpose , ready whenever a guest asks for a slower way to see the neighborhood.", "This second career has not solved every problem facing the trade, however. Most remaining drivers are older men who learned the job from a father or an uncle. Few young workers are willing to take up such a physically demanding role, since it pays far less than driving a taxi or delivering food by motorbike. Local authorities have discussed formal licensing schemes to protect the drivers who remain active in the trade. So far, though, no city has settled on rules that both drivers and regulators find workable."], questions: [{ q: "According to the passage, who is credited with adapting the cyclo's design from earlier rickshaws?", options: ["A French merchant working in Saigon", "A Vietnamese mechanic working in Saigon", "A French mechanic working in Saigon", "A French mechanic working in Hanoi"], answer: 2 }, { q: "The word \"restricted\" in paragraph 3 is closest in meaning to _______.", options: ["limited", "banned", "discouraged", "resisted"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["Tour operators in the Old Quarter now offer cyclo rides for sightseeing.", "Traffic restrictions have ended the use of cyclos in Vietnamese cities entirely.", "Cyclo drivers today earn a stable living mainly from guiding tourist rides.", "The cyclo lost its everyday role but survives through tourism and heritage."], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a use of the cyclo?", options: ["Taking children to school each morning", "Carrying market vendors' vegetables to sell", "Giving tourists guided sightseeing rides daily", "Delivering food orders to customers' homes"], answer: 1 }, { q: "According to the passage, what mainly caused the decline of the cyclo as everyday transport?", options: ["The arrival of cheap imported motorbikes after wartime reforms.", "A sudden rise in private car ownership after the reforms.", "The arrival of cheap imported motorbikes after economic reforms.", "New licensing requirements introduced for cyclo drivers in the cities."], answer: 2 }, { q: "The phrase \"this purpose\" in paragraph 4 refers to _______.", options: ["slow sightseeing tours", "a small vehicle fleet", "the historic core", "colonial buildings nearby"], answer: 0 }, { q: "What can be inferred about the future of the cyclo trade, based on the passage?", options: ["Cities will soon adopt uniform rules that guarantee the trade's survival.", "Fewer young workers joined the trade, which then forced fares lower.", "Foreign tourists increasingly choose cyclo tours over taxi rides nowadays.", "Its survival may depend on how licensing disputes are eventually resolved."], answer: 3 }, { q: "The word \"modest\" in paragraph 2 is closest in meaning to _______.", options: ["insignificant", "reasonable", "limited", "modern"], answer: 1 }, { q: "According to the passage, why are few young people willing to become cyclo drivers today?", options: ["The work is physically demanding and pays less than other jobs.", "The work requires a costly license that few drivers can afford.", "Most families no longer pass the trade down to their children.", "The job pays about the same as delivering food by motorbike."], answer: 0 }, { q: "What is the author's overall attitude toward the future of the cyclo trade?", options: ["Enthusiastic, celebrating the cyclo's complete revival through tourism.", "Critical, blaming city authorities for destroying a valuable tradition.", "Cautiously uncertain, given the unresolved problems facing the trade.", "Confidently optimistic that licensing reforms will resolve disputes soon."], answer: 2 }] },
    { title: "Reforming the Envelope", paragraphs: ["Long before anyone spoke of carbon targets, engineers already used a single word for everything standing between a building's interior and the weather outside: the envelope. Walls, roof, windows, and the layers of insulation packed inside them all belong to this system, and how well it is sealed determines far more than comfort. In most temperate cities, heating and cooling this boundary now accounts for a share of total energy use that rivals transport. That single fact is precisely why reformers have begun treating the envelope itself, rather than the furnace or the air conditioner inside it, as the real target for savings.", "For decades, building codes treated insulation as a minor detail rather than a lever worth pulling. Minimum standards were set low, inspectors rarely tested how much air escaped through gaps around windows, and cheap fiberglass batting was considered adequate almost everywhere. A house built to code in the 1970s might lose as much heat through its walls in a year as a modern equivalent loses in three.", "That indifference has given way, over roughly the last decade, to a wave of code revisions aimed squarely at the envelope. New construction in many jurisdictions must now meet airtightness targets verified by a blower-door test, use windows with far lower heat-transfer ratings, and wrap exterior walls in continuous insulation that older framing methods never required. Regulators argue that tightening these standards is the cheapest available lever for cutting emissions, since it changes a building permanently rather than depending on occupants to behave efficiently.", "Existing buildings pose a harder problem, since a code can govern what gets built tomorrow but not what already stands today. Retrofitting a pre-war apartment block to modern standards often costs more than the building is worth on paper, and the work usually requires displacing tenants for weeks. Some cities offer low-interest loans or tax rebates to offset that cost, though uptake so far has been modest outside wealthier neighborhoods.", "Developers have not welcomed every part of this shift, and their objections are not always dismissed lightly. Tighter envelope rules can add several percent to the upfront cost of a new building, and some builders argue that the requirements are calibrated for colder climates. Such rules, they say, make little sense in milder regions, where the payback period for extra insulation may stretch well beyond a decade. Whether that objection reflects a genuine mismatch or simply reluctance to absorb short-term cost remains a point of dispute among the architects who must apply the rules.", "Independent studies of completed retrofits tend to support the reformers, though the evidence is not uniform across climates. Buildings upgraded to current envelope standards in cold northern cities have shown energy savings that regularly exceed the projections made before construction began. In milder coastal cities, however, measured savings have sometimes fallen short of projections, suggesting that the same code may simply be doing less work where heating and cooling demand was already modest to begin with.", "Given this uneven record, most observers expect envelope reform to keep advancing unevenly rather than through any single national standard. Wealthier cities with ambitious climate targets are likely to keep tightening their codes on their own timetable. Poorer or milder-climate regions, by contrast, may adopt the same rules years later, if at all, once retrofitting costs fall or federal incentives grow large enough to close the remaining gap."], questions: [{ q: "The word \"uptake\" in paragraph 4 is closest in meaning to _______.", options: ["widespread use", "adoption rate", "energy savings", "building upkeep"], answer: 1 }, { q: "According to the passage, what must new construction demonstrate to meet current airtightness standards?", options: ["Verified performance on an annual energy audit.", "Approval from a certified insulation contractor.", "Certification from the regional building inspector's office.", "Verified performance on a blower-door test."], answer: 3 }, { q: "The phrase \"that objection\" in paragraph 5 refers to _______.", options: ["the climate mismatch claim", "the extra insulation payback", "the milder climate regions", "the building's upfront cost"], answer: 0 }, { q: "What is the main idea of the passage?", options: ["New construction must now pass strict airtightness and insulation tests.", "Developer resistance has largely stopped envelope reform from taking hold.", "Building codes now target the envelope, though results and acceptance remain uneven.", "Every building code worldwide now requires the same strict envelope standards."], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a way cities or codes have addressed building energy efficiency?", options: ["Installing rooftop solar panels on new buildings", "Requiring airtightness tests for all new construction nationwide", "Offering tax rebates for retrofitting older buildings", "Allowing poorer regions to adopt standards later"], answer: 0 }, { q: "According to the passage, why do some builders object to tighter envelope rules in milder climates?", options: ["The extra insulation cost is impossible to recover at all.", "Regulators in milder regions refuse to enforce the new codes.", "Cold-climate codes cost far less to implement than expected.", "The extra insulation cost takes too long to pay back."], answer: 3 }, { q: "What can be inferred about envelope reform in milder coastal cities, based on the passage?", options: ["The same codes will eventually be abandoned in these cities entirely.", "Its energy-saving benefits may be smaller there than in colder climates.", "Because the codes save less energy, builders demanded looser standards there.", "Cold northern cities have shown savings exceeding original projections."], answer: 1 }, { q: "The word \"uneven\" in paragraph 7 is closest in meaning to _______.", options: ["disastrous", "modest", "inconsistent", "unproven"], answer: 2 }, { q: "According to the passage, what happened to measured energy savings in mild coastal cities after envelope upgrades?", options: ["They sometimes fell short of the projections made beforehand.", "They consistently exceeded projections made before construction began.", "They remained exactly equal to the original projected figures.", "They were not measured in most of the studies reviewed."], answer: 0 }, { q: "What is the author's overall attitude toward the future of envelope reform?", options: ["Sympathetic mainly to developers who oppose the added construction costs.", "Measured, expecting continued but uneven progress rather than swift change.", "Skeptical that envelope reform provides any real benefit in mild climates.", "Confident that a single national standard will soon unify all codes."], answer: 1 }] },
    { title: "The Conservation Ledger", paragraphs: ["Long before anyone spoke of natural capital, economists had noticed an odd asymmetry in how nations measured their own wealth. A forest counted for nothing in gross domestic product until it was felled and sold as timber, while a wetland registered no value at all unless it was drained and paved over. Out of that asymmetry grew the conservation ledger, a systematic attempt to record ecosystems as assets, complete with debits for degradation and credits for restoration. A coral reef might then sit on the same balance sheet as a factory.", "Constructing such a ledger means assigning numbers to things that were never priced to begin with. Analysts lean on proxies: the cost of an artificial substitute, such as a water-treatment plant standing in for a wetland's filtering function, supplies one figure. The price people say they would pay to preserve a species they will never see supplies another, drawn from carefully worded surveys rather than any market. Neither proxy comes close to capturing an ecosystem's full worth, though both, their designers argue, at least keep that worth from defaulting to zero.", "Governments were slow to take the ledger seriously, but institutional appetite has grown markedly since the early 2010s, and several national statistical agencies now publish natural capital accounts alongside conventional GDP figures. What made this shift possible, more than any scientific breakthrough, was a change already under way inside corporate reporting. Once auditors started demanding a line for environmental liabilities, government statisticians found it harder to justify leaving ecosystems off the books entirely.", "Not every economist, however, has welcomed the ledger's arrival with much enthusiasm or optimism. [1] Critics argue that stacking different valuation methods side by side produces numbers whose apparent precision is misleading. [2] A wetland valued by replacement cost can come out far higher than the same wetland valued by a preference survey, yet both figures get cited with equal confidence. [3] Two studies of the same mangrove forest, using different but equally defensible assumptions, have arrived at valuations differing by an order of magnitude. [4]", "A rather different kind of objection also comes from entirely outside economics. Some ecologists contend that assigning any price to an ecosystem quietly concedes that it could, in principle, be sold. Once a reef has a dollar figure attached, they warn, someone will eventually argue a shopping district is worth more. Proponents reply that this objection mistakes a rhetorical device for policy itself. No serious advocate proposes auctioning reefs; the goal is only to force decision-makers who already treat ecosystems as worthless to reckon with a number instead of a void.", "Whether that reckoning actually changes outcomes on the ground remains genuinely unsettled, and neither side has produced evidence sufficient to close the debate. A handful of jurisdictions that adopted formal accounts have since blocked development projects on the strength of the resulting figures, which supporters cite as proof the ledger has teeth. Far more jurisdictions, however, have compiled the same accounts and approved the projects anyway. That pattern suggests the numbers alone, however carefully constructed, rarely settle a fight that was always more political than arithmetical."], questions: [{ q: "According to the passage, what enabled national statistical agencies to publish natural capital accounts more readily?", options: ["A sudden and unexpected scientific breakthrough proved that ecosystems held measurable financial value.", "A prior shift inside corporate financial reporting made ecosystems harder to omit entirely.", "Several jurisdictions had already blocked major development projects using early ledger figures.", "Economists had quietly developed far more accurate cost proxies for pricing wetlands."], answer: 1 }, { q: "The word \"asymmetry\" in paragraph 1 is closest in meaning to _______.", options: ["catastrophe", "deficit", "asynchrony", "imbalance"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a criticism of the conservation ledger?", options: ["Ledger figures are too complex for ordinary policymakers to interpret correctly.", "Different valuation methods can produce wildly inconsistent figures for one ecosystem.", "Pricing nature risks treating ecosystems as though they could eventually be sold.", "Nearly every jurisdiction that adopts ledger figures ends up approving development anyway."], answer: 0 }, { q: "The phrase \"That pattern\" in paragraph 6 refers to _______.", options: ["the resulting figures cited", "the projects approved anyway", "the ledger's uneven influence", "formal natural capital accounts"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["Economists disagree sharply over which method values wetlands most accurately overall.", "The conservation ledger assigns ecosystems monetary value, but its methods remain disputed.", "Governments now universally rely on ledger accounts to block harmful projects.", "Ecologists have proven that monetizing nature always leads to its eventual sale."], answer: 1 }, { q: "Based on paragraphs 3 and 6, what can be inferred about the relationship between formally adopting natural capital accounts and actually restricting development?", options: ["Formal adoption does not reliably translate into projects actually being blocked.", "Every jurisdiction that formally adopts natural capital accounts will eventually block major projects.", "Because so many projects were approved, fewer jurisdictions chose to adopt formal accounts.", "Central statistical agencies now publish accounts alongside conventional GDP figures."], answer: 0 }, { q: "According to the passage, what specific comparison illustrates how much valuation estimates for the same ecosystem can differ?", options: ["Two coral-reef studies produced valuations differing by only a small margin.", "A single wetland study produced two nearly identical valuations overall.", "Ten separate forest studies each reached the exact same figure.", "Two mangrove-forest studies produced valuations differing by an order of magnitude."], answer: 3 }, { q: "The word \"concedes\" in paragraph 5 is closest in meaning to _______.", options: ["demands", "values", "admits", "conceals"], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Even economists who favor monetary valuation concede that this particular discrepancy is difficult to justify to policymakers.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 3 }, { q: "What is the author's overall attitude toward the conservation ledger's effectiveness?", options: ["Strongly dismissive, viewing the entire ledger project as methodologically worthless.", "Measured skepticism, acknowledging conceptual appeal but doubting practical bite.", "Quietly optimistic that most governments will soon treat ledger figures as binding.", "Confidently persuaded that the ledger has already reshaped global conservation policy."], answer: 1 }] },
    { title: "The Shape of the Argument", paragraphs: ["Philosophers of rhetoric have long distinguished between what an argument claims and how it is built. It is the latter — the underlying architecture rather than the conclusion perched on top of it — that increasingly interests scholars studying why some arguments persuade audiences that logic alone should leave unmoved. A syllogism and a shopping list can share a topic without sharing a shape. That structural dimension is what recent work in argumentation theory has tried, not always successfully, to formalize.", "Not every argument, it turns out, announces its own internal structure honestly to its audience. Some arrange their strongest premise last, building toward it the way a lawyer saves a key witness for closing arguments. By the time an objection would naturally occur to a listener, the emotional momentum of the delivery has often already carried the audience past the point where they would have paused. Others invert this pattern entirely, front-loading the strongest claim and betting that an audience persuaded early will extend charitable interpretation to the weaker points that follow.", "What made argument-mapping software attractive to logicians was a problem already familiar to trial lawyers. [1] An argument's apparent strength often has less to do with any single premise than with how densely its premises are interlinked. [2] A claim resting on three independent, converging lines of support survives the loss of any one considerably better than a claim resting on three premises stacked in series. [3] In a serial chain, a single failure at any link can collapse everything built on top of it, even though both arguments may look equally long on the page. [4]", "This distinction, between convergent and serial support, is not merely a diagrammatic curiosity. It may explain a pattern that has puzzled experimental psychologists for decades. Audiences shown a serial argument frequently rate it as more rigorous than a convergent one of equal length, apparently mistaking the visible chain of reasoning for genuine strength. Yet a single weak link in that chain is enough to sink the entire structure, a vulnerability the convergent form simply does not share.", "Critics of formal argument-mapping counter that reducing a rich, discursive essay to a tree of numbered claims strips away exactly the qualifying language on which the essay's honesty depended. A hedge such as \"the evidence tentatively suggests\" collapses, on most standard maps, into a flat, unqualified arrow between two boxes. The map's tidy geometry may then imply a confidence the original prose never claimed and would likely have disavowed if pressed. Whether this is a defect in the method, or a virtue that exposes evasions the prose was quietly relying on, remains a live dispute among those who build such maps.", "Some defenders of mapping, however, accept this particular criticism only up to a point. They concede that a map flattens hedges much the way a photograph flattens depth. Yet they argue this flattening is diagnostic rather than distorting: an essay whose argument survives translation into a rigid tree probably did not need its hedges to do much work in the first place. One that collapses under translation, by contrast, was arguably relying on its qualifying language to paper over a structural weakness the prose itself was designed to obscure.", "Whichever side eventually prevails, the debate reveals something both camps already agree on beneath their surface disagreement. The shape of an argument is never a neutral vessel for its content. Some claims are true only in the softened, hedge-dependent form in which they were originally offered, and become something closer to false the moment that hedging is stripped away for a cleaner diagram."], questions: [{ q: "According to the passage, what problem, already familiar to trial lawyers, made argument-mapping software attractive to logicians?", options: ["That an argument's strength depends entirely on how many premises it contains.", "That an argument's strength depends more on premise interconnection than any single premise.", "That an argument's strength always depends on the order premises are presented in.", "That an argument's single weakest premise usually determines its overall persuasive power."], answer: 1 }, { q: "The phrase \"that chain\" in paragraph 4 refers to _______.", options: ["genuine overall argumentative strength", "the convergent support form", "decades of psychological puzzlement", "the visible reasoning chain"], answer: 3 }, { q: "The word \"diagnostic\" in paragraph 6 is closest in meaning to _______.", options: ["revealing", "damning", "distorting", "dogmatic"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a criticism or limitation discussed regarding argument structure or mapping?", options: ["Some arguments delay their strongest premise until the end to build momentum.", "Formal maps always strip every trace of qualifying language from an argument.", "Audiences are generally better at spotting serial arguments' weak links than convergent ones'.", "A convergent argument can lose one premise without necessarily losing its overall force."], answer: 2 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Convergent support, in other words, tends to degrade gracefully, while serial support tends to fail catastrophically.'", options: ["[1]", "[2]", "[3]", "[4]"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["An argument's structure shapes its persuasiveness as much as its content does.", "Densely interlinked premises always make an argument objectively stronger than isolated ones.", "Argument-mapping software has fully solved the problem of misleading argument structures.", "Every hedge in an argument is dishonest and should be removed entirely."], answer: 0 }, { q: "According to the passage, what did the experimental psychology finding show about how audiences judge serial versus convergent arguments of equal length?", options: ["Audiences always rate serial arguments as far more rigorous than convergent ones.", "Audiences tend to rate serial arguments as more rigorous than convergent ones.", "Audiences rate convergent arguments as slightly more rigorous than serial ones.", "Audiences show no measurable preference between serial and convergent arguments at all."], answer: 1 }, { q: "Based on the hedged claim in paragraph 6 that an essay surviving translation into a rigid tree \"probably did not need its hedges to do much work,\" what can be inferred about essays that collapse under such translation?", options: ["Their persuasiveness depended entirely on qualifying language rather than any logic.", "All essays using any hedging language will necessarily collapse under formal mapping.", "Because their arguments collapsed under mapping, hedges were added to disguise it.", "Their persuasiveness may have depended more on qualifying language than core logic."], answer: 3 }, { q: "The word \"disavowed\" in paragraph 5 is closest in meaning to _______.", options: ["regretted", "implied", "rejected", "disproved"], answer: 2 }, { q: "What is the author's overall attitude toward the debate between argument-mapping proponents and critics?", options: ["Even-handed, treating both the diagnostic value and distorting risk of mapping as genuine.", "Largely critical, viewing formal argument-mapping as fundamentally dishonest to its source material.", "Firmly supportive, endorsing mapping as a reliable test of an essay's honesty.", "Entirely indifferent, presenting the debate without any interest in its resolution."], answer: 0 }] },
  ] },
];
